// Generated by pipeline/frameworks/leverage.py; kept outside the catalog and
// exam directories so their inventory consumers never mistake it for content.
export type EntryLeverage = { coverage: number; position: number | null }
export type FrameworkLeverage = ReadonlyMap<string, EntryLeverage>

let cache: Promise<FrameworkLeverage | null> | null = null

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function parseLeverage(raw: unknown): FrameworkLeverage | null {
  if (
    !isRecord(raw) ||
    raw.version !== 1 ||
    typeof raw.generated_from !== 'string' ||
    !raw.generated_from.trim() ||
    !isRecord(raw.entries) ||
    Object.keys(raw.entries).length === 0
  )
    return null

  const entries = new Map<string, EntryLeverage>()
  for (const [id, value] of Object.entries(raw.entries)) {
    if (
      !id.trim() ||
      !isRecord(value) ||
      typeof value.coverage !== 'number' ||
      !Number.isSafeInteger(value.coverage) ||
      value.coverage < 0 ||
      (value.position !== null &&
        (typeof value.position !== 'number' ||
          !Number.isFinite(value.position) ||
          value.position <= 0)) ||
      (value.coverage === 0 && value.position !== null)
    )
      return null
    entries.set(id, { coverage: value.coverage, position: value.position })
  }
  return entries
}

/** Memoised fetch, like loadPrereqGraph. Any missing/invalid asset fails open
 *  to catalog ordering; callers still apply the independent prerequisite gate. */
export function loadFrameworkLeverage(): Promise<FrameworkLeverage | null> {
  if (cache) return cache
  cache = (async () => {
    try {
      const response = await fetch('/leverage/framework_leverage.json')
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const data = parseLeverage(await response.json())
      if (!data) throw new Error('invalid data')
      return data
    } catch {
      console.warn(
        '[leverage] framework_leverage.json is missing or invalid — using catalog order (fail open)',
      )
      return null
    }
  })()
  return cache
}

/** Test-only: clear the memoised file. */
export function __resetLeverageCache(): void {
  cache = null
}
